// firstJSAsset reads dist/assets/ at test time and returns the URL path of the
// first .js file found. This makes the test agnostic to Vite's content-hashed
// filenames (Phase 2a replaced the placeholder app.js with hashed builds).
func firstJSAsset(t *testing.T) string {
	t.Helper()
	entries, err := os.ReadDir("dist/assets")
	if err != nil {
		t.Fatalf("read dist/assets: %v", err)
	}
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), ".js") {
			return "/assets/" + e.Name()
		}
	}
	t.Fatal("no .js file in dist/assets — did the SPA build run?")
	return ""
}

// TestHandler_SPAAndCache exercises the S-web-embed joint: the embedded SPA is
// served with the correct cache headers, client-route fallback returns
// index.html (200), broken hashed asset URLs fail fast (404), and a nil
// apiHandler serves the SPA alone. apiHandler is nil because the SPA path has
// no api dependency — proving the embed surface is independent of the api
// router (INV1).
func TestHandler_SPAAndCache(t *testing.T) {
	h := Handler(nil, Options{})
	jsAsset := firstJSAsset(t) // discovered at test time (content-hashed)

	tests := []struct {
		name            string
		method          string
		target          string
		wantStatus      int
		wantInBody      string // substring proving the embedded index.html is served
		wantContentType string // non-empty → asserted as Content-Type prefix
		wantCache       string // substring the Cache-Control header must contain
		notWantCache    string // substring the Cache-Control header must NOT contain
	}{
		{
			name:            "root_serves_index_no_cache",
			target:          "/",
			wantStatus:      http.StatusOK,
			wantInBody:      `<div id="root"`, // React mount point (Vite build)
			wantContentType: "text/html",
			wantCache:       "no-cache",
		},
		{
			name:            "hashed_asset_immutable",
			target:          jsAsset,
			wantStatus:      http.StatusOK,
			wantContentType: "application/javascript",
			wantCache:       "immutable",
			notWantCache:    "no-cache",
		},
		{
			name:            "client_route_falls_back_to_index",
			target:          "/some/client/route",
			wantStatus:      http.StatusOK,
			wantInBody:      `<div id="root"`,
			wantContentType: "text/html",
			wantCache:       "no-cache",
		},
		{
			name:       "missing_asset_404_no_fallback",
			target:     "/assets/missing.js",
			wantStatus: http.StatusNotFound,
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			req := httptest.NewRequest(http.MethodGet, tc.target, nil)
			rec := httptest.NewRecorder()
			h.ServeHTTP(rec, req)

			if rec.Code != tc.wantStatus {
				t.Fatalf("status = %d, want %d", rec.Code, tc.wantStatus)
			}
			body, _ := io.ReadAll(rec.Body)
			if tc.wantInBody != "" && !strings.Contains(string(body), tc.wantInBody) {
				t.Errorf("body missing %q; body=%q", tc.wantInBody, string(body)[:min(120, len(body))])
			}
			ct := rec.Header().Get("Content-Type")
			if tc.wantContentType != "" && !strings.HasPrefix(ct, tc.wantContentType) {
				t.Errorf("Content-Type = %q, want prefix %q", ct, tc.wantContentType)
			}
			cc := rec.Header().Get("Cache-Control")
			if tc.wantCache != "" && !strings.Contains(cc, tc.wantCache) {
				t.Errorf("Cache-Control = %q, want to contain %q", cc, tc.wantCache)
			}
			if tc.notWantCache != "" && strings.Contains(cc, tc.notWantCache) {
				t.Errorf("Cache-Control = %q, must NOT contain %q", cc, tc.notWantCache)
			}
		})
	}

	// Nil apiHandler + GET / returns 200 (already covered by the table, but
	// assert the SPA-alone path explicitly for the INV1-nil contract).
	t.Run("nil_api_handler_root_ok", func(t *testing.T) {
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		rec := httptest.NewRecorder()
		Handler(nil, Options{}).ServeHTTP(rec, req)
		if rec.Code != http.StatusOK {
			t.Fatalf("nil apiHandler: status = %d, want 200", rec.Code)
		}
	})
}

// TestHandler_DevMode asserts Options{DevMode:true} disables the immutable
// asset header (sends no-cache everywhere) — the Vite dev-proxy path.
func TestHandler_DevMode(t *testing.T) {
	h := Handler(nil, Options{DevMode: true})
	req := httptest.NewRequest(http.MethodGet, firstJSAsset(t), nil)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", rec.Code)
	}
	cc := rec.Header().Get("Cache-Control")
	if !strings.Contains(cc, "no-cache") {
		t.Errorf("DevMode /assets Cache-Control = %q, want no-cache", cc)
	}
	if strings.Contains(cc, "immutable") {
		t.Errorf("DevMode /assets Cache-Control = %q, must NOT contain immutable", cc)
	}
}

// TestHandler_Swagger exercises the S-web-swagger joint: /openapi.{yaml,json}
// serve the embedded code-generated spec with the correct Content-Types, and
// /docs/ loads the vendored Swagger UI pointed at /openapi.json. apiHandler is
// nil — the swagger surface is independent of the api router (INV-public-
// contract). The /docs/ case uses a redirect-following server client because
// httpSwagger serves /docs/ via a 301 to /docs/index.html (browsers follow it).
func TestHandler_Swagger(t *testing.T) {
	h := Handler(nil, Options{})

	t.Run("openapi_yaml", func(t *testing.T) {
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/openapi.yaml", nil))
		if rec.Code != http.StatusOK {
			t.Fatalf("status = %d, want 200", rec.Code)
		}
		if ct := rec.Header().Get("Content-Type"); !strings.HasPrefix(ct, "application/yaml") {
			t.Errorf("Content-Type = %q, want application/yaml", ct)
		}
		// The AC-2 verify probe — the spec names a real route.
		if !strings.Contains(rec.Body.String(), "/libraries") {
			t.Errorf("spec body missing /libraries; body=%q", rec.Body.String()[:min(80, rec.Body.Len())])
		}
	})

	t.Run("openapi_json", func(t *testing.T) {
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/openapi.json", nil))
		if rec.Code != http.StatusOK {
			t.Fatalf("status = %d, want 200", rec.Code)
		}
		if ct := rec.Header().Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
			t.Errorf("Content-Type = %q, want application/json", ct)
		}
		if !strings.Contains(rec.Body.String(), "/libraries") {
			t.Errorf("spec body missing /libraries")
		}
	})

	t.Run("docs_ui_loads", func(t *testing.T) {
		srv := httptest.NewServer(h)
		defer srv.Close()
		resp, err := http.Get(srv.URL + "/docs/")
		if err != nil {
			t.Fatalf("GET /docs/: %v", err)
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("GET /docs/ final status = %d, want 200", resp.StatusCode)
		}
		if ct := resp.Header.Get("Content-Type"); !strings.HasPrefix(ct, "text/html") {
			t.Errorf("Content-Type = %q, want text/html", ct)
		}
		body, _ := io.ReadAll(resp.Body)
		if !strings.Contains(strings.ToLower(string(body)), "swagger") {
			t.Errorf("docs body missing 'swagger'; body=%q", string(body)[:min(80, len(body))])
		}
	})
}

// TestHandler_SwaggerNotFallback proves the swagger routes are wired AHEAD of
// the SPA fallback: /openapi.yaml returns the YAML spec (Content-Type
// application/yaml), NOT the SPA index.html (text/html). Without the
// ahead-of-fallback wiring this would leak index.html.
func TestHandler_SwaggerNotFallback(t *testing.T) {
	rec := httptest.NewRecorder()
	Handler(nil, Options{}).ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/openapi.yaml", nil))
	if ct := rec.Header().Get("Content-Type"); strings.HasPrefix(ct, "text/html") {
		t.Fatalf("/openapi.yaml Content-Type = %q — leaked SPA index.html (swagger route not ahead of fallback)", ct)
	}
	if !strings.HasPrefix(rec.Header().Get("Content-Type"), "application/yaml") {
		t.Fatalf("/openapi.yaml Content-Type = %q, want application/yaml", rec.Header().Get("Content-Type"))
	}
}

